/**
 * Unit tests: lib/stripe/idempotency.ts
 *
 * Coverage (7 tests):
 *  1. Same operation + params → deterministic key (idempotent)
 *  2. Different operations → different keys
 *  3. Param key order is canonicalized (sorted) → same key regardless of insertion order
 *  4. null/undefined params produce stable keys
 *  5. Key prefix follows inkos_{operation}_{hash} format
 *  6. withIdempotencyKey passes the key to the wrapped function
 *  7. withIdempotencyKey propagates errors from the wrapped function
 *
 * No DB or external dependencies — runs without Supabase.
 */

import { describe, it, expect } from 'vitest'
import { idempotencyKeyFor, withIdempotencyKey } from '@/lib/stripe/idempotency'

// ---------------------------------------------------------------------------
// idempotencyKeyFor
// ---------------------------------------------------------------------------

describe('idempotencyKeyFor', () => {
  it('generates deterministic keys for same input', () => {
    const k1 = idempotencyKeyFor('connect.account.create', { studio_id: 'abc', type: 'studio' })
    const k2 = idempotencyKeyFor('connect.account.create', { studio_id: 'abc', type: 'studio' })
    expect(k1).toBe(k2)
  })

  it('generates different keys for different ops', () => {
    const k1 = idempotencyKeyFor('connect.account.create', { studio_id: 'abc' })
    const k2 = idempotencyKeyFor('payment_intent.create', { studio_id: 'abc' })
    expect(k1).not.toBe(k2)
  })

  it('canonicalizes param order (sorted keys)', () => {
    const k1 = idempotencyKeyFor('op', { a: 1, b: 2 })
    const k2 = idempotencyKeyFor('op', { b: 2, a: 1 })
    expect(k1).toBe(k2)
  })

  it('null params produce stable keys', () => {
    const k1 = idempotencyKeyFor('op', { artist_id: null })
    const k2 = idempotencyKeyFor('op', { artist_id: null })
    expect(k1).toBe(k2)
  })

  it('returns key prefixed with inkos_ + operation name', () => {
    const k = idempotencyKeyFor('connect.account.create', { studio_id: 'x' })
    expect(k.startsWith('inkos_connect.account.create_')).toBe(true)
  })

  it('generates different keys for different param values', () => {
    const k1 = idempotencyKeyFor('payment_intent.create', { booking_id: 'booking-a' })
    const k2 = idempotencyKeyFor('payment_intent.create', { booking_id: 'booking-b' })
    expect(k1).not.toBe(k2)
  })

  it('empty params object produces a stable key', () => {
    const k1 = idempotencyKeyFor('op', {})
    const k2 = idempotencyKeyFor('op', {})
    expect(k1).toBe(k2)
    expect(k1.startsWith('inkos_op_')).toBe(true)
  })
})

// ---------------------------------------------------------------------------
// withIdempotencyKey
// ---------------------------------------------------------------------------

describe('withIdempotencyKey', () => {
  it('passes the key to the wrapped fn', async () => {
    const key = idempotencyKeyFor('test', {})
    const result = await withIdempotencyKey(key, (k) => Promise.resolve(k))
    expect(result).toBe(key)
  })

  it('propagates errors from the wrapped fn', async () => {
    const key = idempotencyKeyFor('test', {})
    await expect(
      withIdempotencyKey(key, () => Promise.reject(new Error('boom'))),
    ).rejects.toThrow('boom')
  })

  it('returns the wrapped fn return value unchanged', async () => {
    const key = idempotencyKeyFor('test.op', { studio_id: 'studio-1' })
    const fakeAccount = { id: 'acct_test123', object: 'account' }
    const result = await withIdempotencyKey(key, () => Promise.resolve(fakeAccount))
    expect(result).toEqual(fakeAccount)
  })
})

/**
 * RPC contract tests: studio_l2_payments_enabled
 *
 * Coverage (6 tests — DB-gated via describe.skipIf):
 *  1. No connected account → enabled=false, reason='no_connected_account', account_id=null
 *  2. Account pending → enabled=false, reason='onboarding_pending'
 *  3. Account restricted → enabled=false, reason='onboarding_restricted'
 *  4. Account rejected → enabled=false, reason='onboarding_rejected'
 *  5. Account active but charges_enabled=false → enabled=false, reason='charges_disabled'
 *  6. Account active + charges_enabled=true → enabled=true, reason=null, account_id populated
 *
 * Track C migration must be applied for these to pass. Without DB they skip cleanly.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  cleanupStudio,
} from './helpers'
