describe.skipIf(!hasDb)('RPC: studio_l2_payments_enabled', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string

  beforeAll(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
  })

  afterAll(async () => {
    await cleanupStudio(studioId)
  })

  // ---------------------------------------------------------------------------
  // Helper: insert a connected account row directly for test setup.
  // Uses service-role client to bypass RLS. The RPC itself is tested separately.
  // ---------------------------------------------------------------------------
  async function insertConnectedAccount(opts: {
    accountId: string
    onboardingStatus: 'pending' | 'active' | 'restricted' | 'rejected'
    chargesEnabled: boolean
    payoutsEnabled?: boolean
    transfers?: boolean
  }): Promise<void> {
    const { error } = await sb.from('stripe_connected_accounts').insert({
      studio_id: studioId,
      account_id: opts.accountId,
      type: 'studio',
      artist_id: null,
      onboarding_status: opts.onboardingStatus,
      capabilities: {
        charges_enabled: opts.chargesEnabled,
        payouts_enabled: opts.payoutsEnabled ?? false,
        transfers: opts.transfers ?? false,
        tax_reporting_us_1099_nec: false,
      },
      country: 'US',
      default_currency: 'usd',
      restricted_reason: null,
      requirements_due_by: null,
    })
    if (error) throw new Error(`insertConnectedAccount failed: ${error.message}`)
  }

  it('no connected account → enabled=false, reason=no_connected_account, account_id=null', async () => {
    // Use a fresh studio that has no connected account
    const freshStudio = await createTestStudio()

    const args: StudioL2PaymentsEnabledArgs = { studioId: freshStudio.id }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('no_connected_account')
    expect(result.account_id).toBeNull()
    expect(result.onboarding_status).toBeNull()

    await cleanupStudio(freshStudio.id)
  })

  it('account with onboarding_status=pending → enabled=false, reason=onboarding_pending', async () => {
    const accountId = `acct_l2s_pend_${randomUUID().replace(/-/g, '').slice(0, 12)}`
    await insertConnectedAccount({
      accountId,
      onboardingStatus: 'pending',
      chargesEnabled: false,
    })

    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('onboarding_pending')
    expect(result.account_id).toBe(accountId)
    expect(result.onboarding_status).toBe('pending')

    // Cleanup account row to not pollute later sub-tests
    await sb.from('stripe_connected_accounts').delete().eq('account_id', accountId)
  })

  it('account with onboarding_status=restricted → enabled=false, reason=onboarding_restricted', async () => {
    const accountId = `acct_l2s_restr_${randomUUID().replace(/-/g, '').slice(0, 11)}`
    await insertConnectedAccount({
      accountId,
      onboardingStatus: 'restricted',
      chargesEnabled: false,
    })

    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('onboarding_restricted')
    expect(result.onboarding_status).toBe('restricted')

    await sb.from('stripe_connected_accounts').delete().eq('account_id', accountId)
  })

  it('account with onboarding_status=rejected → enabled=false, reason=onboarding_rejected', async () => {
    const accountId = `acct_l2s_rejct_${randomUUID().replace(/-/g, '').slice(0, 11)}`
    await insertConnectedAccount({
      accountId,
      onboardingStatus: 'rejected',
      chargesEnabled: false,
    })

    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('onboarding_rejected')
    expect(result.onboarding_status).toBe('rejected')

    await sb.from('stripe_connected_accounts').delete().eq('account_id', accountId)
  })

  it('account active but charges_enabled=false → enabled=false, reason=charges_disabled', async () => {
    const accountId = `acct_l2s_chgdis_${randomUUID().replace(/-/g, '').slice(0, 10)}`
    await insertConnectedAccount({
      accountId,
      onboardingStatus: 'active',
      chargesEnabled: false,
      payoutsEnabled: true,
      transfers: true,
    })

    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('charges_disabled')
    expect(result.onboarding_status).toBe('active')

    await sb.from('stripe_connected_accounts').delete().eq('account_id', accountId)
  })

  it('account active + charges_enabled=true → enabled=true, reason=null, account_id populated', async () => {
    const accountId = `acct_l2s_ok_${randomUUID().replace(/-/g, '').slice(0, 13)}`
    await insertConnectedAccount({
      accountId,
      onboardingStatus: 'active',
      chargesEnabled: true,
      payoutsEnabled: true,
      transfers: true,
    })

    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(true)
    expect(result.reason).toBeNull()
    expect(result.account_id).toBe(accountId)
